# Definition for a binary tree node.
class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def lca(root: Node, v1: int, v2: int) -> Node:
    def find_path(node, target, path):
        if node is None:
            return False
        path.append(node)
        if node.data == target:
            return True
        if find_path(node.left, target, path) or find_path(node.right, target, path):
            return True
        path.pop()                 # backtrack
        return False

    path1, path2 = [], []
    find_path(root, v1, path1)
    find_path(root, v2, path2)
    ancestor = None
    for a, b in zip(path1, path2):
        if a is b:
            ancestor = a           # last shared node
        else:
            break
    return ancestor

