public Node lca(Node root, int v1, int v2) {
    Node node = root;
    while (node != null) {
        if (v1 < node.data && v2 < node.data) {
            node = node.left;          // both targets smaller → go left
        } else if (v1 > node.data && v2 > node.data) {
            node = node.right;         // both targets larger → go right
        } else {
            return node;               // split point (or one equals node) → LCA
        }
    }
    return null;                       // unreachable if both values exist
}

